:root{
  --bg:#151826;
  --bg-soft:#1a1a2e;
  --panel:#1f2337;
  --panel-2:#252a40;
  --border:#323854;
  --text:#e8ebff;
  --muted:#9ba3c9;
  --brand:#19b8ff;
  --green:#22c55e;
  --red:#ef4444;
  --amber:#f59e0b;
  --radius:10px;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,DM Sans,system-ui,sans-serif;font-size:14px}
a{color:inherit;text-decoration:none}
.container{max-width:1400px;margin:0 auto;padding:12px}
.topnav{position:sticky;top:0;z-index:30;background:#141724;border-bottom:1px solid var(--border)}
.topnav .row{display:flex;align-items:center;gap:14px;padding:10px 12px}
.brand{font-weight:700;color:var(--brand);font-size:18px}
.navlinks{display:flex;gap:8px;flex-wrap:wrap}
.navlinks a{padding:8px 10px;border-radius:8px;color:var(--muted)}
.navlinks a.active,.navlinks a:hover{background:var(--panel);color:var(--text)}
.panel{background:var(--panel);border:1px solid var(--border);border-radius:var(--radius)}
.grid{display:grid;gap:12px}
.market-ticker{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}
.ticker-item{padding:10px;background:var(--panel);border:1px solid var(--border);border-radius:8px}
.sym{font-weight:600}.muted{color:var(--muted)}
.pos{color:var(--green)}.neg{color:var(--red)}
.section-title{display:flex;justify-content:space-between;align-items:center;margin:16px 0 10px}
.section-title h2{margin:0;font-size:16px}
.card{padding:12px}
.table{width:100%;border-collapse:collapse}
.table th,.table td{padding:8px;border-bottom:1px solid var(--border);text-align:left}
.badge{padding:2px 6px;border-radius:999px;background:var(--panel-2);font-size:12px}
.badge.pos{background:rgba(34,197,94,.14)}.badge.neg{background:rgba(239,68,68,.14)}
.spark{height:24px;width:80px}
.hero{display:grid;grid-template-columns:2fr 1fr;gap:12px}
.ideas{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.idea-card img{width:100%;height:120px;object-fit:cover;border-radius:8px}
.toolbar{display:flex;gap:8px;flex-wrap:wrap}
.btn{background:var(--panel-2);border:1px solid var(--border);color:var(--text);padding:6px 10px;border-radius:8px;cursor:pointer}
.btn.active,.btn:hover{border-color:var(--brand);color:#d8f5ff}
.layout-chart{display:grid;grid-template-columns:270px 1fr 310px;gap:10px;height:calc(100vh - 64px);padding:10px}
.watchlist-group h4{margin:0;padding:10px;display:flex;justify-content:space-between;cursor:pointer;background:var(--panel-2);border-radius:8px}
.watchlist-body{padding-top:6px}
.watch-item{display:grid;grid-template-columns:56px 1fr auto;gap:8px;padding:6px;border-bottom:1px solid var(--border)}
.chart-main{display:grid;grid-template-rows:auto 1fr auto;gap:10px}
.candle-area{position:relative;background:linear-gradient(180deg,#171c2e,#101322);border:1px solid var(--border);border-radius:10px;padding:10px}
.candles{display:flex;align-items:flex-end;height:100%;gap:4px}
.candle{width:8px;border-radius:2px 2px 0 0}
.fin-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.tabs{display:flex;gap:8px;flex-wrap:wrap}
.tab-btn{padding:6px 10px;border:1px solid var(--border);background:var(--panel-2);border-radius:8px;cursor:pointer}
.tab-btn.active{border-color:var(--brand)}
.tab-panel{display:none}.tab-panel.active{display:block}
.broker-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.broker{padding:12px}
.stat-banner{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media (max-width:1100px){.layout-chart{grid-template-columns:1fr;height:auto}.hero,.ideas,.broker-cards,.market-ticker{grid-template-columns:1fr 1fr}.stat-banner{grid-template-columns:1fr}}
@media (max-width:700px){.hero,.ideas,.broker-cards,.market-ticker{grid-template-columns:1fr}}
EOF

